begin;
set local search_path=public,extensions;
select plan(40);

select ok((select count(*)=7 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'and c.relname=any(array['notification_preference_categories','notification_template_versions','notification_retry_policy_versions','user_notification_preferences','notification_instances','notification_deliveries','notification_delivery_attempts'])),'seven notification tables exist');
select ok((select count(*)=7 and bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['notification_preference_categories','notification_template_versions','notification_retry_policy_versions','user_notification_preferences','notification_instances','notification_deliveries','notification_delivery_attempts'])),'RLS is enabled on every notification table');
select ok((select count(*)=6 from pg_policies where schemaname='public'and tablename=any(array['notification_preference_categories','notification_template_versions','user_notification_preferences','notification_instances','notification_deliveries','notification_delivery_attempts'])),'six explicit authenticated read policies exist');
select ok(not has_table_privilege('authenticated','public.user_notification_preferences','INSERT')and not has_table_privilege('authenticated','public.notification_instances','UPDATE')and not has_table_privilege('authenticated','public.notification_deliveries','UPDATE'),'authenticated cannot bypass notification RPCs');
select ok(not has_table_privilege('service_role','public.notification_instances','INSERT')and not has_table_privilege('service_role','public.notification_deliveries','UPDATE'),'service worker cannot bypass its narrow RPCs with direct writes');
select ok((select count(*)=6 and bool_and(p.prosecdef and p.proconfig::text like'%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['set_notification_preference','list_notification_center','mark_notification_read','retry_notification_delivery','enqueue_notification','record_notification_delivery_attempt'])),'six public notification RPCs are security definer with fixed search paths');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname like'%notification%'and has_function_privilege('anon',p.oid,'EXECUTE')),'anonymous role cannot execute notification functions');
select ok((select count(*)=4 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE')and not has_function_privilege('service_role',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['set_notification_preference','list_notification_center','mark_notification_read','retry_notification_delivery'])),'four recipient commands are authenticated-only');
select ok((select count(*)=2 and bool_and(has_function_privilege('service_role',p.oid,'EXECUTE')and not has_function_privilege('authenticated',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['enqueue_notification','record_notification_delivery_attempt'])),'enqueue and delivery recording are service-only');
select ok((select count(*)=11 from public.notification_preference_categories where status='ACTIVE'),'V1 categories are seeded');
select ok((select mandatory from public.notification_preference_categories where code='SECURITY_CRITICAL'),'security alerts are mandatory');
select ok((select mandatory from public.notification_preference_categories where code='BILLING_CRITICAL'),'billing alerts are mandatory');
select ok((select count(*)=4 from public.notification_template_versions where status='ACTIVE'and template_code in('SYSTEM_ALERT','MISSION_REMINDER')),'baseline templates retain their four active localized versions');
select ok(not exists(select 1 from(select template_code,version,count(*)filter(where locale='fr-MA')fr,count(*)filter(where locale='ar-MA')ar from public.notification_template_versions group by template_code,version)x where fr<>1 or ar<>1),'every baseline template version has one FR and one AR rendering');
select ok((select bool_and(subject_template<>''and body_template<>'')from public.notification_template_versions where locale='ar-MA'),'Arabic templates contain complete subject and body');
select ok((select mandatory and priority='CRITICAL'and channels@>array['IN_APP','EMAIL']::text[]from public.notification_template_versions where template_code='SYSTEM_ALERT'and locale='fr-MA'and status='ACTIVE'),'critical system alert is mandatory on in-app and email');
select ok((select max_attempts=5 and base_backoff_seconds=60 and max_backoff_seconds=86400 from public.notification_retry_policy_versions where status='ACTIVE'),'versioned retry policy is bounded');
select ok((select count(*)=3 from pg_trigger where tgname=any(array['notification_templates_immutable','notification_retry_policies_immutable','notification_attempts_immutable'])and not tgisinternal),'template/rule content and attempt history are protected');
select ok((select pg_get_functiondef(p.oid)like'%MANDATORY_NOTIFICATION_MUST_BE_IMMEDIATE%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='assert_notification_preference'),'mandatory category guard rejects disabled and digest modes');
select ok(exists(select 1 from pg_constraint where conrelid='public.user_notification_preferences'::regclass and contype='c'and pg_get_constraintdef(oid)like'%DIGEST%'and pg_get_constraintdef(oid)like'%digest_frequency%'),'digest mode requires a frequency');
select ok(exists(select 1 from pg_constraint where conrelid='public.notification_template_versions'::regclass and contype='c'and pg_get_constraintdef(oid)like'%CRITICAL%'and pg_get_constraintdef(oid)like'%mandatory%'),'critical templates are structurally mandatory');
select ok((select pg_get_functiondef(p.oid)like'%is_active_org_member%'and pg_get_functiondef(p.oid)like'%p_user=p_actor%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='notification_recipient_access'),'recipient access binds user and active organization membership');
select ok((select qual like'%notification_recipient_access%'from pg_policies where schemaname='public'and tablename='notification_instances'),'inbox RLS uses recipient plus organization access');
select ok((select qual like'%notification_recipient_access%'from pg_policies where schemaname='public'and tablename='user_notification_preferences'),'preferences RLS uses recipient plus organization access');
select ok((select qual like'%notification_recipient_access%'from pg_policies where schemaname='public'and tablename='notification_delivery_attempts'),'attempt history RLS follows its recipient-scoped notification');
select ok((select pg_get_functiondef(p.oid)like'%begin_contract_command%'and pg_get_functiondef(p.oid)like'%STALE_NOTIFICATION_PREFERENCE%'and pg_get_functiondef(p.oid)like'%row_version%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='set_notification_preference'),'preference changes are idempotent and optimistic-concurrency safe');
select ok((select pg_get_functiondef(p.oid)like'%notification.preference.saved%'and pg_get_functiondef(p.oid)like'%NotificationPreferenceSavedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='set_notification_preference'),'preference changes are audited and emit Outbox');
select ok((select pg_get_functiondef(p.oid)like'%IN_APP%'and pg_get_functiondef(p.oid)like'%status<>''SKIPPED''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='list_notification_center'),'notification center excludes disabled in-app instances');
select ok((select pg_get_functiondef(p.oid)like'%recipient_user_id=a%'and pg_get_functiondef(p.oid)like'%organization_id=p_organization_id%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='list_notification_center'),'notification center query is user and organization scoped');
select ok((select pg_get_functiondef(p.oid)like'%begin_contract_command%'and pg_get_functiondef(p.oid)like'%STALE_NOTIFICATION%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='mark_notification_read'),'mark-read is idempotent and row-version safe');
select ok((select pg_get_functiondef(p.oid)like'%auth.role()is distinct from''service_role''%'and pg_get_functiondef(p.oid)like'%on conflict(recipient_user_id,organization_id,deduplication_key)do nothing%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='enqueue_notification'),'enqueue is service-only and deduplicated');
select ok((select pg_get_functiondef(p.oid)like'%(password|secret|token|api.?key)%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='enqueue_notification'),'enqueue rejects common secret-bearing variable keys');
select ok((select pg_get_functiondef(p.oid)like'%UNKNOWN_NOTIFICATION_VARIABLE%'and pg_get_functiondef(p.oid)like'%variable_keys%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='enqueue_notification'),'enqueue rejects undeclared template variables');
select ok((select pg_get_functiondef(p.oid)like'%MISSING_NOTIFICATION_VARIABLE%'and pg_get_functiondef(p.oid)like'%unnest(t.variable_keys)%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='enqueue_notification'),'enqueue rejects incomplete variables before rendering');
select ok((select pg_get_functiondef(p.oid)like'%mode:=''IMMEDIATE''%'and pg_get_functiondef(p.oid)like'%if t.mandatory%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='enqueue_notification'),'mandatory notifications override preferences to immediate delivery');
select ok((select pg_get_functiondef(p.oid)like'%QUEUED_DIGEST%'and pg_get_functiondef(p.oid)like'%SKIPPED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='enqueue_notification'),'enqueue materializes digest and disabled channel states');
select ok((select pg_get_functiondef(p.oid)like'%power(2,attempt-1)%'and pg_get_functiondef(p.oid)like'%DEAD_LETTER%'and pg_get_functiondef(p.oid)like'%max_attempts%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_notification_delivery_attempt'),'failed delivery uses bounded exponential retry and dead-lettering');
select ok((select pg_get_functiondef(p.oid)like'%idempotency_key=p_idempotency_key%'and pg_get_functiondef(p.oid)like'%NOTIFICATION_ATTEMPT_REPLAYED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_notification_delivery_attempt'),'delivery attempt retries replay safely');
select ok((select pg_get_functiondef(p.oid)like'%status<>''FAILED''%'and pg_get_functiondef(p.oid)like'%begin_contract_command%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='retry_notification_delivery'),'manual retry is restricted to failed delivery and idempotent');
select ok((select count(*)=1 from pg_indexes where schemaname='public'and indexname='notification_delivery_dispatch_idx'and indexdef like'%next_attempt_at%'and indexdef like'%FAILED%'),'dispatcher has a due/retry partial index');

select * from finish();
rollback;
